#include <bits/stdc++.h>
using namespace std;

const long long mod = 998244353;

vector<vector<long long>> identityMatrix(int size) {
    vector<vector<long long>> identity(size, vector<long long>(size, 0));
    for (int i = 0; i < size; i++) {
        identity[i][i] = 1;
    }
    return identity;
}

vector<vector<long long>> multiplyMatrices(const vector<vector<long long>>& a, const vector<vector<long long>>& b) {
    int rowsA = a.size();
    int colsA = a[0].size();
    int colsB = b[0].size();
    vector<vector<long long>> result(rowsA, vector<long long>(colsB, 0));
    for (int i = 0; i < rowsA; i++) {
        for (int j = 0; j < colsB; j++) {
            for (int k = 0; k < colsA; k++) {
                result[i][j] += (a[i][k] % mod) * (b[k][j] % mod);
                result[i][j] %= mod;
            }
        }
    }
    return result;
}

vector<vector<long long>> matrixPower(const vector<vector<long long>>& base, long long exponent) {
    if (exponent == 0) {
        return identityMatrix(base.size());
    }
    if (exponent % 2 == 1) {
        vector<vector<long long>> temp = matrixPower(base, exponent - 1);
        return multiplyMatrices(temp, base);
    }
    vector<vector<long long>> half = matrixPower(base, exponent / 2);
    return multiplyMatrices(half, half);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, m, L, R;
    cin >> n >> m >> L >> R;
    long long h = R - L;
    long long e = 0, o = 0;
    if (h % 2 == 1) {
        long long d = (h + 1) / 2;
        e = d;
        o = d;
    } else {
        long long d = h / 2;
        e = d;
        o = d;
        if (L % 2 == 1) o++;
        else e++;
    }
    vector<vector<long long>> matrix = {{e, o}, {o, e}};
    vector<vector<long long>> powerResult = matrixPower(matrix, n * m);
    long long answer = powerResult[0][0];
    if ((n * m) % 2 == 1) answer += powerResult[0][1];
    cout << answer % mod << "\n";
    return 0;
}
